"""Consistent JSON error handling.

All errors are returned in a single envelope:

    {"error": {"code": <int>, "type": <str>, "message": <str>, "details": <obj|null>}}
"""
from flask import Flask, jsonify
from marshmallow import ValidationError
from werkzeug.exceptions import HTTPException


class APIError(Exception):
    """Raise anywhere in a view to return a structured error response."""

    def __init__(self, message: str, status_code: int = 400, error_type: str | None = None, details=None):
        super().__init__(message)
        self.message = message
        self.status_code = status_code
        self.error_type = error_type or _default_type(status_code)
        self.details = details


def _default_type(status_code: int) -> str:
    return {
        400: "bad_request",
        401: "unauthorized",
        403: "forbidden",
        404: "not_found",
        405: "method_not_allowed",
        409: "conflict",
        422: "validation_error",
        429: "rate_limit_exceeded",
        500: "internal_error",
    }.get(status_code, "error")


def error_response(status_code: int, message: str, error_type: str | None = None, details=None):
    payload = {
        "error": {
            "code": status_code,
            "type": error_type or _default_type(status_code),
            "message": message,
            "details": details,
        }
    }
    return jsonify(payload), status_code


def register_error_handlers(app: Flask) -> None:
    @app.errorhandler(APIError)
    def handle_api_error(err: APIError):
        return error_response(err.status_code, err.message, err.error_type, err.details)

    @app.errorhandler(ValidationError)
    def handle_validation_error(err: ValidationError):
        return error_response(422, "Input validation failed.", "validation_error", err.messages)

    @app.errorhandler(429)
    def handle_rate_limit(err):
        return error_response(429, f"Rate limit exceeded: {err.description}.", "rate_limit_exceeded")

    @app.errorhandler(HTTPException)
    def handle_http_exception(err: HTTPException):
        return error_response(err.code or 500, err.description or err.name)

    @app.errorhandler(Exception)
    def handle_unexpected(err: Exception):  # pragma: no cover - safety net
        app.logger.exception("Unhandled exception")
        return error_response(500, "An unexpected error occurred.")

"""Authentication endpoints: register, login, refresh, current user."""
from flask import request
from flask_jwt_extended import (
    create_access_token,
    create_refresh_token,
    get_jwt_identity,
    jwt_required,
)

from app.api.v1 import api_v1
from app.audit import audit
from app.errors import APIError
from app.extensions import db, limiter
from app.models import User
from app.schemas import LoginSchema, RegisterSchema


def _json_body() -> dict:
    data = request.get_json(silent=True)
    if data is None or not isinstance(data, dict):
        raise APIError("Request body must be a JSON object.", 400)
    return data


@api_v1.post("/auth/register")
@limiter.limit("10 per minute")
def register():
    data = RegisterSchema().load(_json_body())

    if User.query.filter((User.username == data["username"]) | (User.email == data["email"])).first():
        raise APIError("A user with that username or email already exists.", 409)

    user = User(username=data["username"], email=data["email"])
    user.set_password(data["password"])
    db.session.add(user)
    db.session.commit()

    audit("user.register", user_id=user.id, resource_type="user", resource_id=user.id, status_code=201)
    return {"data": user.to_dict()}, 201


@api_v1.post("/auth/login")
@limiter.limit("5 per minute")
def login():
    data = LoginSchema().load(_json_body())

    user = User.query.filter_by(username=data["username"]).first()
    if user is None or not user.check_password(data["password"]):
        audit("auth.login.failure", detail=f"username={data['username']}", status_code=401)
        raise APIError("Invalid username or password.", 401)
    if not user.is_active:
        audit("auth.login.failure", user_id=user.id, detail="inactive account", status_code=403)
        raise APIError("Account is deactivated.", 403)

    identity = str(user.id)
    access_token = create_access_token(identity=identity)
    refresh_token = create_refresh_token(identity=identity)

    audit("auth.login.success", user_id=user.id, status_code=200)
    return {
        "data": {
            "access_token": access_token,
            "refresh_token": refresh_token,
            "token_type": "Bearer",
        }
    }


@api_v1.post("/auth/refresh")
@jwt_required(refresh=True)
def refresh():
    identity = get_jwt_identity()
    access_token = create_access_token(identity=identity)
    audit("auth.token.refresh", user_id=int(identity), status_code=200)
    return {"data": {"access_token": access_token, "token_type": "Bearer"}}


@api_v1.get("/auth/me")
@jwt_required()
def me():
    user = db.session.get(User, int(get_jwt_identity()))
    if user is None:
        raise APIError("User no longer exists.", 401)
    return {"data": user.to_dict()}

"""Item CRUD endpoints (authenticated, owner-scoped)."""
from flask import request
from flask_jwt_extended import get_jwt_identity, jwt_required

from app.api.v1 import api_v1
from app.audit import audit
from app.errors import APIError
from app.extensions import db
from app.models import Item
from app.pagination import paginate
from app.schemas import ItemCreateSchema, ItemUpdateSchema


def _json_body() -> dict:
    data = request.get_json(silent=True)
    if data is None or not isinstance(data, dict):
        raise APIError("Request body must be a JSON object.", 400)
    return data


def _current_user_id() -> int:
    return int(get_jwt_identity())


def _get_owned_item(item_id: int) -> Item:
    item = db.session.get(Item, item_id)
    if item is None:
        raise APIError("Item not found.", 404)
    if item.owner_id != _current_user_id():
        # Owner-scoped API: hide other users' resources.
        raise APIError("Item not found.", 404)
    return item


@api_v1.get("/items")
@jwt_required()
def list_items():
    query = Item.query.filter_by(owner_id=_current_user_id()).order_by(Item.id)
    return paginate(query, "api_v1.list_items")


@api_v1.post("/items")
@jwt_required()
def create_item():
    data = ItemCreateSchema().load(_json_body())
    item = Item(
        name=data["name"],
        description=data.get("description"),
        price=data["price"],
        owner_id=_current_user_id(),
    )
    db.session.add(item)
    db.session.commit()

    audit("item.create", user_id=item.owner_id, resource_type="item", resource_id=item.id, status_code=201)
    return {"data": item.to_dict()}, 201


@api_v1.get("/items/<int:item_id>")
@jwt_required()
def get_item(item_id: int):
    item = _get_owned_item(item_id)
    return {"data": item.to_dict()}


@api_v1.patch("/items/<int:item_id>")
@jwt_required()
def update_item(item_id: int):
    item = _get_owned_item(item_id)
    data = ItemUpdateSchema().load(_json_body())
    if not data:
        raise APIError("At least one updatable field must be provided.", 400)

    for field, value in data.items():
        setattr(item, field, value)
    db.session.commit()

    audit(
        "item.update",
        user_id=item.owner_id,
        resource_type="item",
        resource_id=item.id,
        status_code=200,
        detail=f"fields={sorted(data.keys())}",
    )
    return {"data": item.to_dict()}


@api_v1.delete("/items/<int:item_id>")
@jwt_required()
def delete_item(item_id: int):
    item = _get_owned_item(item_id)
    db.session.delete(item)
    db.session.commit()

    audit("item.delete", user_id=_current_user_id(), resource_type="item", resource_id=item_id, status_code=204)
    return "", 204

"""Application factory."""
from flask import Flask, jsonify

from app.config import CONFIGS
from app.errors import error_response, register_error_handlers
from app.extensions import db, jwt, limiter


def create_app(config_name: str = "development") -> Flask:
    app = Flask(__name__)
    app.config.from_object(CONFIGS[config_name])

    # Extensions
    db.init_app(app)
    jwt.init_app(app)
    limiter.init_app(app)

    # Consistent JSON errors for JWT failures
    @jwt.unauthorized_loader
    def missing_token(reason):
        return error_response(401, f"Missing or invalid credentials: {reason}")

    @jwt.invalid_token_loader
    def invalid_token(reason):
        return error_response(401, f"Invalid token: {reason}")

    @jwt.expired_token_loader
    def expired_token(_header, _payload):
        return error_response(401, "Token has expired.", "token_expired")

    # Blueprints (versioned APIs)
    from app.api.v1 import api_v1

    app.register_blueprint(api_v1)

    register_error_handlers(app)

    @app.get("/health")
    @limiter.exempt
    def health():
        return jsonify({"status": "ok", "versions": ["v1"]})

    with app.app_context():
        db.create_all()

    return app
